PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE users (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            username TEXT NOT NULL UNIQUE,
            name TEXT NOT NULL,
            password_hash TEXT NOT NULL,
            role TEXT NOT NULL DEFAULT 'viewer',
            active INTEGER NOT NULL DEFAULT 1,
            created_at TEXT
        );
CREATE TABLE brands (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            code TEXT NOT NULL UNIQUE,
            name TEXT NOT NULL,
            description TEXT DEFAULT '',
            active INTEGER NOT NULL DEFAULT 1,
            created_at TEXT
        );
CREATE TABLE suppliers (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            code TEXT NOT NULL UNIQUE,
            name TEXT NOT NULL,
            contact_person TEXT DEFAULT '',
            phone TEXT DEFAULT '',
            email TEXT DEFAULT '',
            address TEXT DEFAULT '',
            active INTEGER NOT NULL DEFAULT 1,
            created_at TEXT
        );
CREATE TABLE products (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            sku TEXT NOT NULL UNIQUE,
            brand_id INTEGER REFERENCES brands(id),
            category TEXT DEFAULT '',
            unit TEXT DEFAULT 'pcs',
            cost_price REAL NOT NULL DEFAULT 0,
            sell_price REAL NOT NULL DEFAULT 0,
            min_stock REAL NOT NULL DEFAULT 0,
            stock_qty REAL NOT NULL DEFAULT 0,
            active INTEGER NOT NULL DEFAULT 1,
            created_at TEXT,
            updated_at TEXT
        , cost_price_initial REAL NOT NULL DEFAULT 0, size TEXT DEFAULT '');
CREATE TABLE inbounds (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            doc_no TEXT NOT NULL UNIQUE,
            doc_date TEXT NOT NULL,
            supplier_id INTEGER REFERENCES suppliers(id),
            note TEXT DEFAULT '',
            status TEXT NOT NULL DEFAULT 'draft',
            total_qty REAL NOT NULL DEFAULT 0,
            total_amount REAL NOT NULL DEFAULT 0,
            created_by INTEGER, created_at TEXT,
            posted_by INTEGER, posted_at TEXT,
            void_reason TEXT DEFAULT '', voided_by INTEGER, voided_at TEXT
        , subtotal_amount REAL NOT NULL DEFAULT 0, discount_type TEXT NOT NULL DEFAULT 'percent', discount_value REAL NOT NULL DEFAULT 0, discount_amount REAL NOT NULL DEFAULT 0);
CREATE TABLE inbound_items (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            inbound_id INTEGER NOT NULL REFERENCES inbounds(id) ON DELETE CASCADE,
            product_id INTEGER NOT NULL REFERENCES products(id),
            qty REAL NOT NULL DEFAULT 0,
            unit_cost REAL NOT NULL DEFAULT 0,
            subtotal REAL NOT NULL DEFAULT 0,
            note TEXT DEFAULT ''
        , discount_share REAL NOT NULL DEFAULT 0, unit_cost_net REAL NOT NULL DEFAULT 0, subtotal_net REAL NOT NULL DEFAULT 0);
CREATE TABLE outbounds (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            doc_no TEXT NOT NULL UNIQUE,
            doc_date TEXT NOT NULL,
            destination TEXT DEFAULT '',
            channel TEXT DEFAULT '',
            note TEXT DEFAULT '',
            status TEXT NOT NULL DEFAULT 'draft',
            total_qty REAL NOT NULL DEFAULT 0,
            total_amount REAL NOT NULL DEFAULT 0,
            created_by INTEGER, created_at TEXT,
            posted_by INTEGER, posted_at TEXT,
            void_reason TEXT DEFAULT '', voided_by INTEGER, voided_at TEXT
        , pos_uuid TEXT DEFAULT '');
CREATE TABLE outbound_items (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            outbound_id INTEGER NOT NULL REFERENCES outbounds(id) ON DELETE CASCADE,
            product_id INTEGER NOT NULL REFERENCES products(id),
            qty REAL NOT NULL DEFAULT 0,
            unit_price REAL NOT NULL DEFAULT 0,
            subtotal REAL NOT NULL DEFAULT 0,
            note TEXT DEFAULT ''
        , cogs REAL NOT NULL DEFAULT 0, cogs_unit REAL NOT NULL DEFAULT 0);
CREATE TABLE adjustments (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            doc_no TEXT NOT NULL UNIQUE,
            doc_date TEXT NOT NULL,
            reason TEXT DEFAULT '',
            note TEXT DEFAULT '',
            status TEXT NOT NULL DEFAULT 'posted',
            total_items INTEGER NOT NULL DEFAULT 0,
            total_delta REAL NOT NULL DEFAULT 0,
            created_by INTEGER, created_at TEXT,
            posted_by INTEGER, posted_at TEXT,
            void_reason TEXT DEFAULT '', voided_by INTEGER, voided_at TEXT
        );
CREATE TABLE adjustment_items (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            adjustment_id INTEGER NOT NULL REFERENCES adjustments(id) ON DELETE CASCADE,
            product_id INTEGER NOT NULL REFERENCES products(id),
            qty_before REAL NOT NULL DEFAULT 0,
            qty_after REAL NOT NULL DEFAULT 0,
            delta REAL NOT NULL DEFAULT 0,
            note TEXT DEFAULT ''
        );
CREATE TABLE opnames (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            doc_no TEXT NOT NULL UNIQUE,
            doc_date TEXT NOT NULL,
            note TEXT DEFAULT '',
            status TEXT NOT NULL DEFAULT 'draft',
            total_items INTEGER NOT NULL DEFAULT 0,
            total_diff REAL NOT NULL DEFAULT 0,
            created_by INTEGER, created_at TEXT,
            posted_by INTEGER, posted_at TEXT,
            void_reason TEXT DEFAULT '', voided_by INTEGER, voided_at TEXT
        );
CREATE TABLE opname_items (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            opname_id INTEGER NOT NULL REFERENCES opnames(id) ON DELETE CASCADE,
            product_id INTEGER NOT NULL REFERENCES products(id),
            qty_system REAL NOT NULL DEFAULT 0,
            qty_counted REAL NOT NULL DEFAULT 0,
            diff REAL NOT NULL DEFAULT 0,
            note TEXT DEFAULT ''
        );
CREATE TABLE returns (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            doc_no TEXT NOT NULL UNIQUE,
            doc_date TEXT NOT NULL,
            type TEXT NOT NULL,
            party TEXT DEFAULT '',
            ref_doc_no TEXT DEFAULT '',
            note TEXT DEFAULT '',
            status TEXT NOT NULL DEFAULT 'draft',
            total_qty REAL NOT NULL DEFAULT 0,
            total_amount REAL NOT NULL DEFAULT 0,
            created_by INTEGER, created_at TEXT,
            posted_by INTEGER, posted_at TEXT,
            void_reason TEXT DEFAULT '', voided_by INTEGER, voided_at TEXT
        , pos_uuid TEXT DEFAULT '');
CREATE TABLE return_items (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            return_id INTEGER NOT NULL REFERENCES returns(id) ON DELETE CASCADE,
            product_id INTEGER NOT NULL REFERENCES products(id),
            qty REAL NOT NULL DEFAULT 0,
            unit_price REAL NOT NULL DEFAULT 0,
            subtotal REAL NOT NULL DEFAULT 0,
            note TEXT DEFAULT ''
        );
CREATE TABLE ledger (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            move_date TEXT NOT NULL,
            product_id INTEGER NOT NULL REFERENCES products(id),
            qty_change REAL NOT NULL DEFAULT 0,
            qty_after REAL NOT NULL DEFAULT 0,
            ref_type TEXT NOT NULL,
            ref_id INTEGER,
            ref_no TEXT DEFAULT '',
            note TEXT DEFAULT '',
            user_id INTEGER,
            created_at TEXT
        , unit_cost REAL NOT NULL DEFAULT 0);
CREATE TABLE counters (
            k TEXT PRIMARY KEY,
            v INTEGER NOT NULL DEFAULT 0
        );
CREATE TABLE activity_log (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER,
            username TEXT DEFAULT '',
            action TEXT NOT NULL,
            detail TEXT DEFAULT '',
            ref_type TEXT DEFAULT '',
            ref_no TEXT DEFAULT '',
            created_at TEXT
        );
CREATE TABLE stock_layers (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            product_id INTEGER NOT NULL REFERENCES products(id) ON DELETE CASCADE,
            move_date TEXT NOT NULL,
            ledger_id INTEGER,
            ref_type TEXT NOT NULL DEFAULT '',
            ref_id INTEGER,
            ref_no TEXT DEFAULT '',
            qty_original REAL NOT NULL DEFAULT 0,
            qty_remaining REAL NOT NULL DEFAULT 0,
            unit_cost REAL NOT NULL DEFAULT 0,
            created_at TEXT
        );
CREATE TABLE layer_uses (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            layer_id INTEGER NOT NULL REFERENCES stock_layers(id) ON DELETE CASCADE,
            product_id INTEGER NOT NULL REFERENCES products(id) ON DELETE CASCADE,
            ledger_id INTEGER,
            move_date TEXT NOT NULL,
            ref_type TEXT NOT NULL DEFAULT '',
            ref_id INTEGER,
            ref_no TEXT DEFAULT '',
            qty REAL NOT NULL DEFAULT 0,
            unit_cost REAL NOT NULL DEFAULT 0,
            total_cost REAL NOT NULL DEFAULT 0,
            created_at TEXT
        );
CREATE TABLE settings (
            k TEXT PRIMARY KEY,
            v TEXT NOT NULL DEFAULT ''
        );
CREATE TABLE report_log (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            type TEXT NOT NULL,
            period_key TEXT NOT NULL,
            period_from TEXT DEFAULT '',
            period_to TEXT DEFAULT '',
            period_label TEXT DEFAULT '',
            status TEXT NOT NULL DEFAULT 'sent',
            recipients INTEGER NOT NULL DEFAULT 0,
            detail TEXT DEFAULT '',
            created_at TEXT
        );
DELETE FROM sqlite_sequence;
CREATE INDEX idx_ledger_product ON ledger(product_id, id);
CREATE INDEX idx_ledger_date ON ledger(move_date);
CREATE INDEX idx_ledger_ref ON ledger(ref_type, ref_id);
CREATE INDEX idx_inbound_items_doc ON inbound_items(inbound_id);
CREATE INDEX idx_outbound_items_doc ON outbound_items(outbound_id);
CREATE INDEX idx_adj_items_doc ON adjustment_items(adjustment_id);
CREATE INDEX idx_opname_items_doc ON opname_items(opname_id);
CREATE INDEX idx_return_items_doc ON return_items(return_id);
CREATE INDEX idx_layers_product ON stock_layers(product_id, id);
CREATE INDEX idx_layer_uses_ref ON layer_uses(ref_type, ref_id);
CREATE INDEX idx_report_log ON report_log(type, period_key, status);
COMMIT;
